package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FumaChromatinCliTest {
    @TempDir Path dir;
    private record Data(List<Map<String,String>> rows) { }
    private static Data table(Path file)throws Exception{var lines=Files.readAllLines(file);String[] header=lines.get(0).split("\t",-1);var rows=new java.util.ArrayList<Map<String,String>>();for(String line:lines.subList(1,lines.size())){String[] fields=line.split("\t",-1);assertEquals(header.length,fields.length);var row=new LinkedHashMap<String,String>();for(int i=0;i<header.length;i++)row.put(header[i],fields[i]);rows.add(row);}return new Data(rows);}
    private Map<String,String> options()throws Exception{
        var original=AdmixtureInputs.decode(Files.readAllBytes(Path.of("examples/fuma/mapping/options.json")));var o=new LinkedHashMap<String,String>();original.forEach((k,v)->o.put(k.toString(),v.toString()));
        for(String k:List.copyOf(o.keySet()))if(k.startsWith("pos-")||k.startsWith("eqtl-")||List.of("window-bp","consequences","consequence-regex","eqtls").contains(k))o.remove(k);o.put("positional","none");o.put("eqtl","none");o.put("chromatin","supplied");o.put("ci-membership","source-global");o.put("ci-coordinates","source-closed");o.put("ci-enhancers","none");o.put("ci-promoters","none");o.put("ci-cadd","0");o.put("ci-rdb","none");o.put("ci-states","none");o.put("ci-binary","none");o.put("empty","retain");o.put("out",dir.resolve("out").toString());
        Path interactions=dir.resolve("interactions.tsv");Files.writeString(interactions,"interaction_id\tregion1\tregion2\tgenes\trsIDs\ttissue\nI1\t1:100-200\t1:250-350\tG2\trs1;rs2\tBrain cortex\n");o.put("interactions",interactions.toString());return o;
    }
    private int run(Map<String,String> options,String... extra)throws Exception{Path carrier=dir.resolve("options.json");Files.writeString(carrier,RegenieRuntime.json(options));var args=new java.util.ArrayList<>(List.of("--mapping-options-file",carrier.toString()));args.addAll(List.of(extra));return FumaToolsCli.run(args.toArray(String[]::new),new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream()));}
    @Test void chromatinOnlyWorkflowRetainsEvidenceAndHashes()throws Exception{var o=options();assertEquals(0,run(o));Path out=Path.of(o.get("out"));assertEquals(2,table(out.resolve("chromatin-evidence.tsv")).rows().size());assertEquals("true",table(out.resolve("genes.tsv")).rows().get(0).get("chromatin_declared"));String session=Files.readString(out.resolve("session.json"));assertTrue(session.contains("source-global"));assertTrue(session.contains("interactions.tsv"));assertTrue(Files.readString(out.resolve("WARNINGS.md")).contains("Required action"));}
    @Test void perInteractionDoesNotAdmitCrossRowListedSnps()throws Exception{var o=options();Files.writeString(Path.of(o.get("interactions")),"interaction_id\tregion1\tregion2\tgenes\trsIDs\ttissue\nI1\t1:100-100\t1:250-350\tG2\trs4\tA\nI2\t1:250-250\t1:100-200\tG1\trs1\tB\n");assertEquals(0,run(o));assertEquals(2,table(Path.of(o.get("out"),"chromatin-evidence.tsv")).rows().size());o.put("out",dir.resolve("strict").toString());assertEquals(0,run(o,"--ci-membership","per-interaction"));assertTrue(table(Path.of(o.get("out"),"genes.tsv")).rows().isEmpty());}
    @Test void bedCoordinateChoiceChangesLowerBoundaryMembership()throws Exception{var o=options();assertEquals(0,run(o,"--ci-coordinates","bed"));var e=table(Path.of(o.get("out"),"chromatin-evidence.tsv")).rows();assertEquals(1,e.size());assertEquals("u2",e.get(0).get("uid"));}
    @Test void promoterReplacementAndLiteralKeysAreAudited()throws Exception{var o=options();Path p=dir.resolve("promoters.tsv");Files.writeString(p,"region2\tgenes\n1:250-350\tG1\n");o.put("ci-promoters",p.toString());assertEquals(0,run(o));assertEquals("G1",table(Path.of(o.get("out"),"chromatin-evidence.tsv")).rows().get(0).get("gene"));String ledger=Files.readString(Path.of(o.get("out"),"chromatin-interactions.tsv"));assertTrue(ledger.contains("G2\tG1\tG1"));}
    @Test void originalUnsupportedDeclarationGetsNoFabricatedGwasOrLdValues()throws Exception{var o=options();Files.writeString(Path.of(o.get("interactions")),"interaction_id\tregion1\tregion2\tgenes\trsIDs\ttissue\nI1\t1:100-100\t1:250-350\tG2\trs4\tA\nI2\t1:250-250\t1:100-200\tG1\trs1\tB\n");Path p=dir.resolve("promoters.tsv");Files.writeString(p,"region2\tgenes\n1:250-350\tG2\n");o.put("ci-promoters",p.toString());assertEquals(0,run(o));var gene=table(Path.of(o.get("out"),"genes.tsv")).rows().get(0);assertEquals("NA",gene.get("min_gwas_p"));assertEquals("0",gene.get("chromatin_variants"));assertEquals("",gene.get("independent_rsIDs"));assertTrue(Files.readString(Path.of(o.get("out"),"WARNINGS.md")).contains("RETAINED WITHOUT FINAL SUPPORT"));var session=AdmixtureInputs.decode(Files.readAllBytes(Path.of(o.get("out"),"session.json")));assertEquals(0,((Number)session.get("mapped_genes")).intValue());assertEquals(1,((Number)session.get("retained_gene_rows")).intValue());assertTrue(Files.readString(Path.of(o.get("out"),"analysis-status.json")).contains("completed-empty"));o.put("out",dir.resolve("unsupported-error").toString());assertEquals(2,run(o,"--empty","error"));assertFalse(Files.exists(Path.of(o.get("out"),"genes.tsv")));assertTrue(Files.exists(Path.of(o.get("out"),"partial/chromatin-interactions.tsv")));}
    @Test void missingDependencyDataAndWrongPolicyFailWithNamedRecovery()throws Exception{var o=options();o.put("ci-enhancers",dir.resolve("absent.tsv").toString());assertEquals(2,run(o));assertFalse(Files.exists(Path.of(o.get("out"),"genes.tsv")));assertTrue(Files.readString(Path.of(o.get("out"),"WARNINGS.md")).contains("Required action"));o.put("out",dir.resolve("bad-policy").toString());o.put("ci-enhancers","none");assertEquals(2,run(o,"--ci-coordinates","inferred"));}
    @Test void overlapBudgetFailureQuarantinesAndDisabledModuleRejectsOptions()throws Exception{var o=options();assertEquals(2,run(o,"--ci-max-overlaps","1"));assertFalse(Files.exists(Path.of(o.get("out"),"genes.tsv")));assertTrue(Files.isDirectory(Path.of(o.get("out"),"partial")));o.put("out",dir.resolve("disabled").toString());assertEquals(2,run(o,"--chromatin","none"));}
    @Test void oneBinaryTrackWorksWithSharedAnnotationFilter()throws Exception{var o=options();o.put("ci-binary","b1");o.put("ci-binary-method","any");assertEquals(0,run(o));assertEquals(2,table(Path.of(o.get("out"),"chromatin-evidence.tsv")).rows().size());}
}

